  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPA-058",
   "what_failed": "Using season-to-season stability of a player's top sequential suppressor as evidence of a stable role.",
   "why": "Recorded as a powered null: only 2/30 stars met the 75% stability rule, so role-level stability was not established under that rule."
